class Twitter {

    private final List<int[]> tweets = new ArrayList<>(); // {userId, tweetId} in posting order
    private final Map<Integer, Set<Integer>> following =
        new HashMap<>();

    public Twitter() {}

    public void postTweet(int userId, int tweetId) {
        tweets.add(new int[] { userId, tweetId });
    }

    public List<Integer> getNewsFeed(int userId) {
        Set<Integer> f = following.getOrDefault(
            userId,
            Collections.emptySet()
        );
        List<Integer> res = new ArrayList<>();

        for (
            int i = tweets.size() - 1;
            i >= 0 && res.size() < 10;
            i--
        ) {
            // newest first
            int[] t = tweets.get(i);
            if (t[0] == userId || f.contains(t[0])) res.add(t[1]);
        }
        return res;
    }

    public void follow(int followerId, int followeeId) {
        following
            .computeIfAbsent(followerId, x -> new HashSet<>())
            .add(followeeId);
    }

    public void unfollow(int followerId, int followeeId) {
        Set<Integer> f = following.get(followerId);
        if (f != null) f.remove(followeeId);
    }
}

