class Twitter {

    private int time = 0;
    private final Map<Integer, List<int[]>> tweets = new HashMap<>(); // userId -> list of {time, tweetId}
    private final Map<Integer, Set<Integer>> following =
        new HashMap<>();

    public Twitter() {}

    public void postTweet(int userId, int tweetId) {
        tweets
            .computeIfAbsent(userId, x -> new ArrayList<>())
            .add(new int[] { time++, tweetId });
    }

    public List<Integer> getNewsFeed(int userId) {
        // heap entry: {time, tweetId, userId, index in that user's list}, newest on top
        PriorityQueue<int[]> pq = new PriorityQueue<>(
            (a, b) -> b[0] - a[0]
        );
        Set<Integer> users = new HashSet<>(
            following.getOrDefault(userId, Collections.emptySet())
        );
        users.add(userId); // a user always sees their own tweets
        for (int u : users) {
            List<int[]> list = tweets.get(u);
            if (list == null || list.isEmpty()) continue;
            int idx = list.size() - 1;
            int[] t = list.get(idx);
            pq.offer(new int[] { t[0], t[1], u, idx });
        }
        List<Integer> res = new ArrayList<>();
        while (!pq.isEmpty() && res.size() < 10) {
            int[] top = pq.poll();
            res.add(top[1]);
            int idx = top[3] - 1; // next older tweet of the same user
            if (idx >= 0) {
                int[] t = tweets.get(top[2]).get(idx);
                pq.offer(new int[] { t[0], t[1], top[2], idx });
            }
        }
        return res;
    }

    public void follow(int followerId, int followeeId) {
        following
            .computeIfAbsent(followerId, x -> new HashSet<>())
            .add(followeeId);
    }

    public void unfollow(int followerId, int followeeId) {
        Set<Integer> f = following.get(followerId);
        if (f != null) f.remove(followeeId);
    }
