class Heap {
    constructor(cmp = (a, b) => a - b) {
        this.a = [];
        this.cmp = cmp;
    } // cmp < 0 means a goes on top
    size() {
        return this.a.length;
    }
    peek() {
        return this.a[0];
    }

    push(x) {
        const a = this.a;
        a.push(x);
        let i = a.length - 1;
        while (i > 0) {
            // sift up
            const p = (i - 1) >> 1;
            if (this.cmp(a[i], a[p]) >= 0) break;
            [a[i], a[p]] = [a[p], a[i]];
            i = p;
        }
    }
    pop() {
        const a = this.a,
            top = a[0],
            last = a.pop();
        if (a.length) {
            a[0] = last;
            let i = 0;
            while (true) {
                // sift down
                const l = 2 * i + 1,
                    r = l + 1;
                let m = i;
                if (l < a.length && this.cmp(a[l], a[m]) < 0) m = l;
                if (r < a.length && this.cmp(a[r], a[m]) < 0) m = r;
                if (m === i) break;
                [a[i], a[m]] = [a[m], a[i]];
                i = m;
            }
        }
        return top;
    }
}

