class MedianFinder {

    private final List<Integer> nums = new ArrayList<>();

    public MedianFinder() {}

    public void addNum(int num) {
        int lo = 0,
            hi = nums.size();
        while (lo < hi) {
            // first index with value >= num
            int mid = (lo + hi) >>> 1;
            if (nums.get(mid) < num) lo = mid + 1;
            else hi = mid;
        }
        nums.add(lo, num); // O(n) shift
    }

    public double findMedian() {
        int n = nums.size();
        if (n % 2 == 1) return nums.get(n / 2);
        return ((long) nums.get(n / 2 - 1) + nums.get(n / 2)) / 2.0;
    }
}

