class MedianFinder {
    private final PriorityQueue<Integer> small = new PriorityQueue<>(Collections.reverseOrder()); // max-
    heap
    private final PriorityQueue<Integer> large = new PriorityQueue<>();                                  // min-
    heap

    public MedianFinder() {}

    public void addNum(int num) {
        small.offer(num);
        large.offer(small.poll());               // keep every small <= every large
        if (large.size() > small.size()) {       // keep small.size() == large.size() or +1
            small.offer(large.poll());
        }
    }

    public double findMedian() {
        if (small.size() > large.size()) return small.peek();
        return ((long) small.peek() + large.peek()) / 2.0;
    }
}

