class Solution {

    private final Random rand = new Random();

    public int findKthLargest(int[] nums, int k) {
        int target = nums.length - k; // index in ascending order
        int lo = 0,
            hi = nums.length - 1;
        while (true) {
            int pivot = nums[lo + rand.nextInt(hi - lo + 1)];
            // [lo..lt-1] < pivot, [lt..gt] == pivot, [gt+1..hi] > pivot
            int lt = lo,
                i = lo,
                gt = hi;
            while (i <= gt) {
                if (nums[i] < pivot) swap(nums, lt++, i++);
                else if (nums[i] > pivot) swap(nums, i, gt--);
                // do not advance i: new nums[i] is unchecked
                else i++;
            }
            if (target < lt) hi = lt - 1;
            else if (target > gt) lo = gt + 1;
            else return pivot;
        }
    }

    private void swap(int[] a, int i, int j) {
        int t = a[i];
        a[i] = a[j];
        a[j] = t;
    }
}

