class Solution {

    public int leastInterval(char[] tasks, int n) {
        int[] cnt = new int[26];
        for (char c : tasks) cnt[c - 'A']++;
        PriorityQueue<Integer> pq = new PriorityQueue<>(
            Collections.reverseOrder()
        );
        for (int c : cnt) if (c > 0) pq.offer(c);
        Deque<int[]> cooling = new ArrayDeque<>(); // {remaining count, time when it is ready again}
        int time = 0;
        while (!pq.isEmpty() || !cooling.isEmpty()) {
            time++;
            if (!pq.isEmpty()) {
                int c = pq.poll() - 1;
                if (c > 0) cooling.offer(new int[] { c, time + n });
            }
            if (
                !cooling.isEmpty() && cooling.peek()[1] == time
            ) pq.offer(cooling.poll()[0]);
        }

        return time;
    }
}

