    let time = 0,
        head = 0;
    while (heap.length || head < cooling.length) {
        time++;
        if (heap.length) {
            heap.sort((a, b) => b - a);
            const c = heap.shift() - 1;
            if (c > 0) cooling.push([c, time + n]);
        }
        if (head < cooling.length && cooling[head][1] === time)
            heap.push(cooling[head++][0]);
    }
    return time;
};

