class Solution {

    public int leastInterval(char[] tasks, int n) {
        int[] cnt = new int[26];
        int maxF = 0;
        for (char c : tasks) maxF = Math.max(maxF, ++cnt[c - 'A']);
        int maxCount = 0;
        for (int c : cnt) if (c == maxF) maxCount++; // tasks that share the top frequency
        int frames = (maxF - 1) * (n + 1) + maxCount; // slots forced by the most frequent task
        return Math.max(tasks.length, frames); // no idle time if tasks overflow the frames
    }
}

