class Solution {

    public void heapify(int[] nums, int ind, int val) {
        int old = nums[ind];
        nums[ind] = val;
        if (val < old) siftUp(nums, ind);
        else siftDown(nums, ind, nums.length);
    }

    private void siftUp(int[] a, int i) {
        while (i > 0) {
            int p = (i - 1) / 2;
            if (a[i] >= a[p]) break; // parent already smaller: heap is fine
            swap(a, i, p);
            i = p;
        }
    }

    private void siftDown(int[] a, int i, int n) {
        while (true) {
            int l = 2 * i + 1,
                r = 2 * i + 2,
                smallest = i;
            if (l < n && a[l] < a[smallest]) smallest = l;
            if (r < n && a[r] < a[smallest]) smallest = r;
            if (smallest == i) break; // both children are >= a[i]
            swap(a, i, smallest);
            i = smallest;
        }
    }

    private void swap(int[] a, int i, int j) {
        int t = a[i];
        a[i] = a[j];
        a[j] = t;
    }
}

