class Solution {

    public List<String> findWords(char[][] board, String[] words) {
        List<String> res = new ArrayList<>();
        Set<String> done = new HashSet<>();
        for (String w : words) {
            if (!done.contains(w) && exist(board, w)) {
                res.add(w);
                done.add(w);
            }
        }
        return res;
    }

    private boolean exist(char[][] b, String w) {
        for (int i = 0; i < b.length; i++) for (
            int j = 0;
            j < b[0].length;
            j++
        ) if (dfs(b, w, i, j, 0)) return true;
        return false;
    }

    private boolean dfs(char[][] b, String w, int i, int j, int k) {
        if (k == w.length()) return true;
        if (
            i < 0 ||
            j < 0 ||
            i >= b.length ||
            j >= b[0].length ||
            b[i][j] != w.charAt(k)
        ) return false;
        char c = b[i][j];
        b[i][j] = '#'; // mark visited
        boolean found =
            dfs(b, w, i + 1, j, k + 1) ||
            dfs(b, w, i - 1, j, k + 1) ||
            dfs(b, w, i, j + 1, k + 1) ||
            dfs(b, w, i, j - 1, k + 1);
        b[i][j] = c; // restore
        return found;
    }
}

