class Solution {

    private static class Node {

        Node[] next = new Node[26];
        String word; // non-null if a word ends here (and has not been found yet)
    }

    public List<String> findWords(char[][] board, String[] words) {
        Node root = new Node();
        for (String w : words) {
            Node cur = root;
            for (char c : w.toCharArray()) {
                int i = c - 'a';
                if (cur.next[i] == null) cur.next[i] = new Node();
                cur = cur.next[i];
            }
            cur.word = w;
        }
        List<String> res = new ArrayList<>();
        for (int i = 0; i < board.length; i++) for (
            int j = 0;
            j < board[0].length;
            j++
        ) dfs(board, i, j, root, res);
        return res;
    }

    private void dfs(
        char[][] b,
        int i,
        int j,
        Node parent,
        List<String> res
    ) {
        if (i < 0 || j < 0 || i >= b.length || j >= b[0].length) return;
        char c = b[i][j];
        if (c == '#' || parent.next[c - 'a'] == null) return; // visited, or no word continues this way
        Node node = parent.next[c - 'a'];
        if (node.word != null) {
            res.add(node.word);
            node.word = null; // report each word once
        }
        b[i][j] = '#';
        dfs(b, i + 1, j, node, res);
        dfs(b, i - 1, j, node, res);
        dfs(b, i, j + 1, node, res);
        dfs(b, i, j - 1, node, res);
        b[i][j] = c;
        if (node.word == null && isLeaf(node)) parent.next[c - 'a'] =
            null; // prune finished branch
    }

    private boolean isLeaf(Node node) {
        for (Node child : node.next) if (child != null) return false;
        return true;
    }
}

