var findWords = function (board, words) {
    const root = { next: {}, word: null };

    for (const w of words) {
        let cur = root;
        for (const ch of w) {
            if (!cur.next[ch]) cur.next[ch] = { next: {}, word: null };
            cur = cur.next[ch];
        }
        cur.word = w;
    }
    const m = board.length,
        n = board[0].length,
        res = [];
    const dfs = (i, j, parent) => {
        if (i < 0 || j < 0 || i >= m || j >= n) return;
        const ch = board[i][j];
        const node = parent.next[ch];
        if (ch === "#" || !node) return;
        if (node.word !== null) {
            res.push(node.word);
            node.word = null;
        }
        board[i][j] = "#";
        dfs(i + 1, j, node);
        dfs(i - 1, j, node);
        dfs(i, j + 1, node);
        dfs(i, j - 1, node);
        board[i][j] = ch;
        if (node.word === null && Object.keys(node.next).length === 0)
            delete parent.next[ch]; // prune
    };
    for (let i = 0; i < m; i++)
        for (let j = 0; j < n; j++) dfs(i, j, root);
    return res;
};

