        for (const ch of s) {
            cur = cur.next[ch.charCodeAt(0) - 97];
            if (!cur) return null;
        }
        return cur;
    }
    countWordsEqualTo(word) {
        const node = this.walk(word);
        return node ? node.endCount : 0;
    }
    countWordsStartingWith(prefix) {
        const node = this.walk(prefix);
        return node ? node.prefixCount : 0;
    }
    erase(word) {
        if (this.countWordsEqualTo(word) === 0) return;
        let cur = this.root;
        for (const ch of word) {
            cur = cur.next[ch.charCodeAt(0) - 97];
            cur.prefixCount--;
        }
        cur.endCount--;
    }
}

