    public String longestWord(String[] words) {
        Set<String> set = new HashSet<>(Arrays.asList(words));
        String best = "";
        for (String w : words) {
            // skip words that cannot beat the current best
            if (
                w.length() < best.length() ||
                (w.length() == best.length() && w.compareTo(best) >= 0)
            ) continue;
            boolean ok = true;
            for (int i = 1; i < w.length() && ok; i++) {
                if (!set.contains(w.substring(0, i))) ok = false;
            }
            if (ok) best = w;
        }
        return best;
    }
}

