class Solution {

    private static class Node {

        Node[] next = new Node[26];
        boolean isEnd;
    }

    public String longestWord(String[] words) {
        Node root = new Node();
        for (String w : words) {
            Node cur = root;
            for (char c : w.toCharArray()) {
                int i = c - 'a';
                if (cur.next[i] == null) cur.next[i] = new Node();
                cur = cur.next[i];
            }
            cur.isEnd = true;
        }
        String best = "";
        for (String w : words) {
            if (
                allPrefixesExist(root, w) &&
                (w.length() > best.length() ||
                    (w.length() == best.length() &&
                        w.compareTo(best) < 0))
            ) {
                best = w;
            }
        }
        return best;
    }

    private boolean allPrefixesExist(Node root, String w) {
        Node cur = root;
        for (char c : w.toCharArray()) {
            cur = cur.next[c - 'a'];
            if (!cur.isEnd) return false; // this prefix is not a word in the list
        }
        return true;
    }
}

