class Solution {

    private static class Node {

        Node[] next = new Node[2];
    }

    public int findMaximumXOR(int[] nums) {
        Node root = new Node();
        int best = 0;
        for (int x : nums) {
            insert(root, x);
            best = Math.max(best, maxXorWith(root, x));
        }
        return best;
    }

    private void insert(Node root, int x) {
        Node cur = root;
        for (int b = 30; b >= 0; b--) {
            // values fit in 31 bits (non-negative int)
            int bit = (x >> b) & 1;
            if (cur.next[bit] == null) cur.next[bit] = new Node();
            cur = cur.next[bit];
        }
    }

    private int maxXorWith(Node root, int x) {
        Node cur = root;
        int res = 0;
        for (int b = 30; b >= 0; b--) {
            int bit = (x >> b) & 1,
                want = bit ^ 1;
            if (cur.next[want] != null) {
                // opposite bit available: this XOR bit becomes 1
                res |= 1 << b;
                cur = cur.next[want];
            } else {
                cur = cur.next[bit];
            }
        }
        return res;
    }
}

