        Integer[] order = new Integer[q];
        for (int i = 0; i < q; i++) order[i] = i;
        Arrays.sort(order, (a, b) ->
            Integer.compare(queries[a][1], queries[b][1])
        ); // by m ascending

        Node root = new Node();
        int[] ans = new int[q];
        int p = 0;
        for (int idx : order) {
            int x = queries[idx][0],
                m = queries[idx][1];
            while (p < nums.length && nums[p] <= m)
                insert(root, nums[p++]); // add newly allowed numbers
            ans[idx] = p == 0 ? -1 : maxXorWith(root, x);
        }
